#!/usr/bin/env python3
"""RoboPaint acrylic copy, one persistent episode. Generate and execute RGB-derived brush paths."""
import sys,os,json,time,argparse,math
import numpy as np
from PIL import Image
from scipy.ndimage import gaussian_filter,distance_transform_edt
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot

ROOT='/app/output'
TARGET='/app/target.png'
PLAN=ROOT+'/paint_plan.npz'
PROGRESS=ROOT+'/paint_progress.json'
COLORS=np.array([[190,191,170],[206,173,135],[149,171,164],[191,147,114],[113,144,149],[155,132,113],[81,133,156],[121,103,93],[72,105,120],[20,90,129],[248,244,236]],dtype=float)
# Broad underpainting first, then upper colour bands, then final light accents.
ORDER=[9,3,7,8,1,6,2,5,4,0]  # zero-based palette order; last colour is paint01
WELLS=[(-.160,.150),(-.130,.1485),(-.100,.147),(-.070,.1455),(-.040,.144),
       (-.160,.180),(-.130,.1785),(-.100,.177),(-.070,.1755),(-.040,.174)]
Z_BY_WIDTH={24:.012,18:.014,11:.016,7:.018}
DT=.2
Q=(0.,1.,0.,0.)
PITCH=8
MINLEN=8

def image_to_labels():
    im=np.asarray(Image.open(TARGET).convert('RGB'),dtype=np.float32)
    sm=gaussian_filter(im,(2,2,0))
    return ((sm[:,:,None,:]-COLORS[None,None,:,:])**2).sum(3).argmin(2).astype(np.uint8)

def make_runs(L):
    D=[distance_transform_edt(L==i).astype(np.float32) for i in range(10)]
    out=[]
    for v in range(PITCH//2,1024,PITCH):
        a=L[v]; ends=np.r_[0,np.where(a[:-1]!=a[1:])[0]+1,1024]
        for u0,u1 in zip(ends[:-1],ends[1:]):
            c=int(a[u0]); n=int(u1-u0)
            if c>=10 or n<MINLEN:continue
            vals=D[c][v,u0:u1]
            if n>20:
                k=min(8,n//4);vals=vals[k:n-k]
            dist=float(np.percentile(vals,35))
            w=24 if dist>=11 else 18 if dist>=8 else 11 if dist>=5 else 7
            pad=min(w/2-1,(n-1)/3)
            out.append((c,int(v),int(round(u0+pad)),int(round(u1-1-pad)),w,int(u0),int(u1)))
    return out

def make_graph(L,S):
    from collections import defaultdict
    rows=defaultdict(list); g=[[] for _ in S]
    for i,s in enumerate(S):rows[s[1]].append(i)
    for v in sorted(rows):
        for i in rows[v]:
            ci,_,ai,bi,*_=S[i]
            for j in rows.get(v+PITCH,[]):
                cj,_,aj,bj,*_=S[j]
                if ci!=cj:continue
                lo=max(ai,aj);hi=min(bi,bj)
                if hi-lo<4:continue
                xs=np.arange(lo,hi+1,2)
                valid=np.all(L[v:v+PITCH+1,xs]==ci,axis=0)
                inds=np.where(valid)[0]
                if len(inds)==0:continue
                x=int(xs[inds[len(inds)//2]])
                g[i].append((j,x));g[j].append((i,x))
    seen=set();comps=[]
    for i in range(len(S)):
        if i in seen:continue
        todo=[i];seen.add(i);nodes=[]
        while todo:
            a=todo.pop();nodes.append(a)
            for b,_ in g[a]:
                if b not in seen:seen.add(b);todo.append(b)
        comps.append(nodes)
    return g,comps

def pix_to_world(u,v,z):
    mm=.227185/1024
    return np.array([-.1+(512-v)*mm,(512-u)*mm,z,*Q],dtype=np.float32)

class Builder:
    def __init__(self):self.actions=[];self.boundaries=[];self.strokes=0;self.current=np.array([-.04,.17,.08,*Q],dtype=np.float32)
    def move(self,p,hold=0):
        p=np.asarray(p,dtype=np.float32);d=float(np.linalg.norm(p[:3]-self.current[:3])); n=max(1,math.ceil(d/.02))
        for k in range(1,n+1):self.actions.append(self.current+(p-self.current)*k/n)
        self.current=p
        for _ in range(hold):self.actions.append(p.copy())
    def pix(self,u,v,w,hold=0):self.move(pix_to_world(u,v,Z_BY_WIDTH[w]),hold)
    def dip(self,c):
        x,y=WELLS[c]
        self.move([x,y,.060,*Q],hold=2)
        self.move([x,y,.018,*Q],hold=3)
        self.move([x,y,.060,*Q],hold=1)
    def component(self,S,g,nodes):
        node_set=set(nodes);root=max(nodes,key=lambda k:S[k][3]-S[k][2]); c,v,u0,u1,w,*_=S[root]
        self.move(pix_to_world(u0,v,.055),hold=3)
        self.pix(u0,v,w,hold=3)
        seen={root};self.strokes+=1
        def dfs(i,entry):
            c,v,a,b,w,*_=S[i]
            self.pix(a,v,w,hold=1);self.pix(b,v,w,hold=1)
            for j,x in sorted(g[i],key=lambda e:abs(e[1]-b)):
                if j not in node_set or j in seen:continue
                seen.add(j)
                self.pix(x,v,w)
                self.pix(x,v,7)
                self.pix(x,S[j][1],7)
                dfs(j,x)
                self.pix(x,S[j][1],7)
                self.pix(x,v,7)
                self.pix(x,v,w)
            self.pix(entry,v,w)
        dfs(root,u0)
        self.move(pix_to_world(u0,v,.055),hold=2)
        if len(seen)!=len(node_set):raise RuntimeError('graph traversal missed nodes')


def generate():
    L=image_to_labels();S=make_runs(L);g,comps=make_graph(L,S)
    if len(comps)>407:raise RuntimeError(f'too many contacts: {len(comps)}')
    b=Builder();cutoffs={};log=[]
    for c in ORDER:
        b.dip(c)
        cc=[nodes for nodes in comps if S[nodes[0]][0]==c]
        # Large regions first; the route stays reasonably local by sorting component centroids.
        cc.sort(key=lambda nodes:(-len(nodes),sum(S[i][1] for i in nodes)/len(nodes)))
        for nodes in cc:b.component(S,g,nodes)
        b.move([-.04,.17,.08,*Q],hold=2)
        cutoffs[str(c+1)]=len(b.actions)
        log.append({'paint':c+1,'components':len(cc),'runs':sum(map(len,cc)),'rows_to_here':len(b.actions)})
    A=np.asarray(b.actions,dtype=np.float32)
    np.savez_compressed(PLAN,actions=A,cutoffs=json.dumps(cutoffs),log=json.dumps(log))
    print(json.dumps({'strokes':b.strokes,'runs':len(S),'action_rows':len(A),'sim_seconds_nominal':len(A)*DT,'by_color':log},indent=2),flush=True)
    return A,cutoffs,log

def load_plan():
    if not os.path.exists(PLAN):return generate()
    p=np.load(PLAN);return p['actions'],json.loads(str(p['cutoffs'])),json.loads(str(p['log']))

def write_progress(d):
    q=PROGRESS+'.tmp';open(q,'w').write(json.dumps(d,indent=2));os.replace(q,PROGRESS)

def execute(until_paint=None):
    A,cutoffs,log=load_plan();r=Robot()
    prog=json.load(open(PROGRESS)) if os.path.exists(PROGRESS) else {'row':0,'calls':None,'strokes_planned':sum(x['components'] for x in log)}
    end=len(A) if until_paint is None else cutoffs[str(until_paint)]
    row=int(prog['row']);print('starting',row,'of',end,'status',r.status(),flush=True)
    while row<end:
        chunk=A[row:min(end,row+40)];pre=r.status();before=pre['calls']
        try:
            res=r.submit('ee_pose',chunk,dt=DT,cameras=['scene_cam'],video='none',note=f'plan rows {row}:{row+len(chunk)}')
            ran=int(res.meta.get('executed_rows',len(chunk)))
            if ran<=0:raise RuntimeError('call executed no rows')
        except Exception as e:
            print('submit exception',repr(e),flush=True)
            status=r.wait_ready();print('resumed',status,flush=True)
            if status['calls']>before:ran=len(chunk)
            else:continue
        row+=ran;prog['row']=row;prog['calls']=r.status()['calls'];write_progress(prog)
        if row%400<40 or row>=end:print('progress',row,'/',end,'time',r.status()['elapsed_s'],flush=True)
    obs=r.get_obs(cameras=['canvas_cam','scene_cam'])
    Image.fromarray(obs.last['canvas_cam']).save(f'{ROOT}/canvas_after_{until_paint or "all"}.png')
    print('finished',row,'status',r.status(),flush=True)

if __name__=='__main__':
    ap=argparse.ArgumentParser();ap.add_argument('--generate-only',action='store_true');ap.add_argument('--until-paint',type=int)
    args=ap.parse_args()
    if args.generate_only:generate()
    else:execute(args.until_paint)
